'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let idx = 0;
const budget = input[idx++];
const n = input[idx++];
const m = input[idx++];

const graph = Array.from({ length: n + 1 }, () => []);

for (let i = 0; i < m; i++) {
  const a = input[idx++];
  const b = input[idx++];
  const time = input[idx++];
  const cost = input[idx++];

  graph[a].push([b, time, cost]);
  graph[b].push([a, time, cost]);
}

const start = input[idx++];
const destination = input[idx++];

const width = budget + 1;
const dist = new Float64Array((n + 1) * width);
dist.fill(Infinity);

const maxHeapSize = 2 * m * width + 5;
const heapIds = new Int32Array(maxHeapSize);
const heapTimes = new Float64Array(maxHeapSize);
let heapSize = 0;
let poppedId = 0;
let poppedTime = 0;

function push(id, time) {
  let pos = heapSize++;
  while (pos > 0) {
    const parent = (pos - 1) >> 1;
    if (heapTimes[parent] <= time) break;
    heapIds[pos] = heapIds[parent];
    heapTimes[pos] = heapTimes[parent];
    pos = parent;
  }
  heapIds[pos] = id;
  heapTimes[pos] = time;
}

function pop() {
  poppedId = heapIds[0];
  poppedTime = heapTimes[0];

  const lastId = heapIds[--heapSize];
  const lastTime = heapTimes[heapSize];

  if (heapSize === 0) return;

  let pos = 0;
  while (true) {
    const left = pos * 2 + 1;
    if (left >= heapSize) break;

    const right = left + 1;
    let child = left;
    if (right < heapSize && heapTimes[right] < heapTimes[left]) child = right;
    if (heapTimes[child] >= lastTime) break;

    heapIds[pos] = heapIds[child];
    heapTimes[pos] = heapTimes[child];
    pos = child;
  }

  heapIds[pos] = lastId;
  heapTimes[pos] = lastTime;
}

const startId = start * width;
dist[startId] = 0;
push(startId, 0);

let answer = -1;

while (heapSize > 0) {
  pop();

  if (poppedTime !== dist[poppedId]) continue;

  const node = Math.floor(poppedId / width);
  const spent = poppedId - node * width;

  if (node === destination) {
    answer = poppedTime;
    break;
  }

  for (const [next, time, cost] of graph[node]) {
    const nextSpent = spent + cost;
    if (nextSpent > budget) continue;

    const nextId = next * width + nextSpent;
    const nextTime = poppedTime + time;

    if (nextTime < dist[nextId]) {
      dist[nextId] = nextTime;
      push(nextId, nextTime);
    }
  }
}

console.log(answer);
